#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <vector>

using DefaultCalc = double;

static float sensor_value(size_t pixel, int channel, int seed) {
    uint32_t v = uint32_t(pixel * 747796405u + uint32_t(channel) * 2891336453u + uint32_t(seed) * 277803737u);
    v = ((v >> ((v >> 28) + 4)) ^ v) * 277803737u;
    v = (v >> 22) ^ v;
    return float(v & 0x00ffffffu) / 16777215.0f;
}

template<class T>
static int run_case(int width, int height, int seed) {
    const size_t n = size_t(width) * size_t(height);
    std::vector<float> input(n * 8);
    for (size_t p = 0; p < n; ++p)
        for (int c = 0; c < 8; ++c) input[p * 8 + c] = sensor_value(p, c, seed);

    std::vector<T> feature_a(n), feature_b(n), score(n);
    const T one = T(1);
    for (size_t p = 0; p < n; ++p) {
        const float* x = &input[p * 8];
        T u = T(x[0]) * T(x[1]) + T(0.35) * T(x[2]) * T(x[3]) - T(0.20) * T(x[4]) - T(0.17);
        T v = T(x[5]) * T(x[6]) - T(0.25) * T(x[7]) + T(0.10) * T(x[0]) - T(0.13);
        feature_a[p] = u / (one + std::abs(u));
        feature_b[p] = v / (one + std::abs(v));
    }
    for (size_t p = 0; p < n; ++p) {
        const float* x = &input[p * 8];
        T d0 = T(x[3]) - T(x[7]);
        T d1 = T(x[1]) - T(x[6]);
        T z = T(0.12) + T(0.66) * T(x[0]) - T(0.39) * T(x[1])
            + T(0.31) * T(x[2]) * T(x[4]) - T(0.27) * T(x[5])
            + T(0.45) * feature_a[p] - T(0.26) * feature_b[p]
            + T(0.13) * feature_a[p] * feature_b[p]
            + T(0.17) * d0 * d0 - T(0.08) * d1 * d1;
        score[p] = T(0.5) + T(0.5) * z / (one + std::abs(z));
    }

    double bins[32][3] = {};
    for (size_t i = 0; i < n; ++i) {
        const double q = static_cast<double>(score[i]);
        const int b = int(i % 32);
        bins[b][0] += q;
        bins[b][1] += q * q;
        bins[b][2] += q >= 0.5 ? 1.0 : 0.0;
    }
    const size_t ids[7] = {0, n / 17, n / 5, n / 2, (3 * n) / 4, (16 * n) / 17, n - 1};
    const size_t storage = input.capacity() * sizeof(float)
        + (feature_a.capacity() + feature_b.capacity() + score.capacity()) * sizeof(T);
    std::cout << std::setprecision(12) << "{\"storage_bytes\":" << storage << ",\"checksums\":[";
    for (int b = 0; b < 32; ++b) {
        if (b) std::cout << ',';
        std::cout << '[' << bins[b][0] << ',' << bins[b][1] << ',' << bins[b][2] << ']';
    }
    std::cout << "],\"samples\":[";
    for (int i = 0; i < 7; ++i) {
        if (i) std::cout << ',';
        std::cout << static_cast<double>(score[ids[i]]);
    }
    std::cout << "]}\n";
    return 0;
}

int main(int argc, char** argv) {
    const int width = argc > 1 ? std::atoi(argv[1]) : 64;
    const int height = argc > 2 ? std::atoi(argv[2]) : 48;
    const int seed = argc > 3 ? std::atoi(argv[3]) : 19;
    const bool audit = argc > 4 && std::strcmp(argv[4], "--audit") == 0;
    if (width < 1 || height < 1 || width > 4096 || height > 2160) return 2;
    return audit ? run_case<double>(width, height, seed) : run_case<DefaultCalc>(width, height, seed);
}
import json
import math
import pathlib
import struct
import subprocess
import sys
import tempfile
import time

root = pathlib.Path(__file__).resolve().parents[1]
source = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else root / "core.cpp"
width, height, seed = 41, 29, 37
n = width * height
scores = []
buckets = [[0.0, 0.0, 0] for _ in range(32)]

def input_value(pixel, channel, seed_value):
    v = (pixel * 747796405 + channel * 2891336453 + seed_value * 277803737) & 0xffffffff
    shift = (v >> 28) + 4
    v = (((v >> shift) ^ v) * 277803737) & 0xffffffff
    v = (v >> 22) ^ v
    value = (v & 0x00ffffff) / 16777215.0
    return struct.unpack("f", struct.pack("f", value))[0]

def norm(value):
    return value / (1.0 + abs(value))

for pixel in range(n):
    x = [input_value(pixel, c, seed) for c in range(8)]
    a = norm(x[0]*x[1] + 0.35*x[2]*x[3] - 0.20*x[4] - 0.17)
    b = norm(x[5]*x[6] - 0.25*x[7] + 0.10*x[0] - 0.13)
    d0, d1 = x[3]-x[7], x[1]-x[6]
    z = (0.12 + 0.66*x[0] - 0.39*x[1] + 0.31*x[2]*x[4] - 0.27*x[5]
         + 0.45*a - 0.26*b + 0.13*a*b + 0.17*d0*d0 - 0.08*d1*d1)
    score = 0.5 + 0.5*z/(1.0+abs(z))
    scores.append(score)
    row = buckets[pixel % 32]
    row[0] += score
    row[1] += score*score
    row[2] += int(score >= 0.5)
ids = [0, n//17, n//5, n//2, 3*n//4, 16*n//17, n-1]

with tempfile.TemporaryDirectory() as temp_dir:
    executable = pathlib.Path(temp_dir) / "pixel-classifier"
    subprocess.run(["c++", "-O3", "-std=c++17", "-DNDEBUG", "-march=native", str(source), "-o", str(executable)], check=True)
    start = time.perf_counter()
    proc = subprocess.run([str(executable), str(width), str(height), str(seed)], capture_output=True, text=True, check=True)
    elapsed = time.perf_counter() - start
result = json.loads(proc.stdout)
assert result["storage_bytes"] <= 140 * 1024 * 1024
assert len(result["samples"]) == len(ids) and len(result["checksums"]) == 32
assert all(math.isfinite(v) for v in result["samples"])
assert all(len(row) == 3 and all(math.isfinite(v) for v in row) for row in result["checksums"])
expected = [scores[i] for i in ids]
assert max(abs(a-b) for a,b in zip(result["samples"], expected)) <= 2e-5
for b in range(32):
    count = (n + 31 - b) // 32
    assert abs(result["checksums"][b][0] - buckets[b][0]) / count <= 2e-5
    assert abs(result["checksums"][b][1] - buckets[b][1]) / count <= 2e-5
    assert abs(result["checksums"][b][2] - buckets[b][2]) <= 4
print(json.dumps({"public_smoke":"PASS", "pixels":n, "storage_bytes":result["storage_bytes"], "elapsed_seconds":elapsed, "samples":len(ids), "checksum_buckets":32}))

